using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches for stickers from public sticker sets that correspond to any of the given emoji
    /// </summary>
    public Task<TdLib.TdApi.Objects.Stickers> SearchStickersAsync(StickerType stickerType = default, string emojis = default, string query = default, string[] inputLanguageCodes = default, int offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("SearchStickersAsync", typeof(SearchStickers).FullName ?? "SearchStickersAsync");

           try
           {
             return client.SearchStickersAsync(stickerType, emojis, query, inputLanguageCodes, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
